		}
		if (record == null) {
			return DataType.DEFAULT;
		}
		long id = record.getLongValue(ComponentDBAdapter.COMPONENT_DT_ID_COL);
		if (id == -1) {
			return DataType.DEFAULT;
		}
		DataType dt = dataMgr.getDataType(id);
		if (dt == null) {
			return BadDataType.dataType;
		}
		return dt;
