			return false; // NOTE: We could check to see if any editable Settings are defined
		}

		/* @Override */
		public bool isChangeAllowed(SettingsDefinition settingsDefinition) {
			if (settingsDefinition is TypeDefSettingsDefinition) {
				return false;
			}
			foreach (SettingsDefinition def in getDataType().getSettingsDefinitions()) {
				if (def.equals(settingsDefinition)) {
					return true;
				}
			}
			return false;
		}

